async function openDashboard(context) {
  const storage = await context.getCapability("document-storage");
  const listed = await storage?.list() || [];
  const matches = listed.filter(
    (doc) => doc.type === DASHBOARD_TYPE || doc.metadata?.singleton === DASHBOARD_TYPE || doc.type === DASHBOARD_TYPE && doc.title === DASHBOARD_TITLE
  );
  if (matches.length > 1) {
    context.log.warn(
      `Found ${matches.length} dashboard documents; opening the oldest and not creating another`
    );
  }
  const existing = matches.slice().sort((a, b) => {
    const aTime = a.createdAt ? new Date(a.createdAt).getTime() : 0;
    const bTime = b.createdAt ? new Date(b.createdAt).getTime() : 0;
    return aTime - bTime;
  })[0];
  if (existing?.id) {
    await context.executeCommand("document.open", { id: existing.id });
    return existing.id;
  }
  const created = await context.executeCommand("document.create", {
    type: DASHBOARD_TYPE,
    title: DASHBOARD_TITLE,
    metadata: { singleton: DASHBOARD_TYPE }
  });
  if (created?.id) {
    await context.executeCommand("document.open", { id: created.id });
    return created.id;
  }
  context.log.warn("Could not create a dashboard document");
  return null;
}

